    "title": "不少剖宫产妈妈在生产时会有这样的体验\\n明明打了麻药肚子还有拉扯感\\n难道是麻药没打够吗？\\n其实……\\n \\n划重点👉：其实大多数情况下，这是正常的。\\n \\n目前剖宫产最常用的麻醉方式有腰麻、硬膜外麻醉或腰硬联合麻醉，这些都是椎管内麻醉，也就是大家常说的「半麻」。\\n \\n麻醉医生会把局部麻醉药注入产妇的椎管内，暂时阻断脊神经的「信号传递」，让下半身失去痛觉和运动功能，但产妇的大脑始终是清醒的。\\n \\n💡关键在于：麻醉阻断的是痛觉，而不是触觉和本体感觉。\\n \\n也就是说，你能感觉到医生在操作、有牵",
